20	
21		app := &App{}
22		if err := app.ExportSplit(in, []pdf.OutputFileSpec{
23			{Pages: []int{1, 2, 3}, Name: "invoice", OutDir: outDir},
24		}, nil); err != nil {
25			t.Fatal(err)
26		}
27	
28		out := filepath.Join(outDir, "invoice.pdf")
29		if _, err := os.Stat(out); err != nil {
30			t.Fatalf("expected output file %s: %v", out, err)
31		}
32		if got, err := pdf.PageCount(out); err != nil {
33			t.Fatal(err)
34		} else if got != 3 {
35			t.Errorf("got %d pages, want 3", got)
36		}
